function(container, apiUrl, tables) {
  let selectedProducts = [];
  let allProducts = [];
  let stores = [];
  let demandPredictions = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 明日の日付を納期の初期値に設定
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  container.querySelector('#delivery-date').value = tomorrow.toISOString().split('T')[0];

  // 店舗データの読み込み
  async function loadStores() {
    const storeData = await window.aivicApi.list(1); // 店舗マスタ
    if (storeData) {
      stores = storeData;
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      stores.forEach(store => {
        if (store.有効フラグ) {
          storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
        }
      });
    }
  }

  // 商品データの読み込み
  async function loadProducts() {
    const productData = await window.aivicApi.list(2); // 商品マスタ
    if (productData) {
      allProducts = productData.filter(p => p.有効フラグ);
    }
  }

  // 需要予測データの読み込み
  async function loadDemandPredictions() {
    const predictionData = await window.aivicApi.list(9); // 需要予測結果
    if (predictionData) {
      demandPredictions = predictionData;
    }
  }

  // 商品一覧の描画
  function renderProductList(products) {
    const tbody = container.querySelector('#product-list');
    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted">該当する商品が見つかりません</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.商品ID);
      const predictedQty = prediction ? prediction.予測数量 : 0;

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>
            ${predictedQty}個
            ${predictedQty > 0 ? `<button type="button" class="prediction-btn" data-product-id="${product.商品ID}">根拠</button>` : ''}
          </td>
          <td><input type="number" class="input quantity-input" min="0" value="${predictedQty}" data-product-id="${product.商品ID}"></td>
          <td class="subtotal">¥0</td>
          <td><button type="button" class="action-btn secondary add-product-btn" data-product-id="${product.商品ID}">追加</button></td>
        </tr>
      `;
    }).join('');

    // 小計の計算
    updateSubtotals();
  }

  // 選択商品一覧の描画
  function renderSelectedProducts() {
    const tbody = container.querySelector('#selected-products');
    if (selectedProducts.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="muted">発注商品を選択してください</td></tr>';
      return;
    }

    tbody.innerHTML = selectedProducts.map(item => {
      const prediction = demandPredictions.find(p => p.商品ID === item.商品ID);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const subtotal = (item.単価 || 0) * (item.発注数量 || 0);

      return `
        <tr data-id="${item.商品ID}">
          <td>${item.商品コード || ''}</td>
          <td>${item.商品名 || ''}</td>
          <td>¥${(item.単価 || 0).toLocaleString()}</td>
          <td>
            ${predictedQty}個
            ${predictedQty > 0 ? `<button type="button" class="prediction-btn" data-product-id="${item.商品ID}">根拠</button>` : ''}
          </td>
          <td><input type="number" class="input quantity-input selected-quantity" min="0" value="${item.発注数量 || 0}" data-product-id="${item.商品ID}"></td>
          <td class="subtotal">¥${subtotal.toLocaleString()}</td>
          <td><button type="button" class="action-btn secondary remove-product-btn" data-product-id="${item.商品ID}">削除</button></td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // 小計の更新
  function updateSubtotals() {
    const rows = container.querySelectorAll('#product-list tr[data-id]');
    rows.forEach(row => {
      const productId = row.dataset.id;
      const product = allProducts.find(p => p.商品ID === productId);
      const quantityInput = row.querySelector('.quantity-input');
      const subtotalCell = row.querySelector('.subtotal');

      if (product && quantityInput && subtotalCell) {
        const quantity = parseInt(quantityInput.value) || 0;
        const subtotal = (product.単価 || 0) * quantity;
        subtotalCell.textContent = `¥${subtotal.toLocaleString()}`;
      }
    });
  }

  // 発注総額の更新
  function updateTotalAmount() {
    let total = 0;
    selectedProducts.forEach(item => {
      total += (item.単価 || 0) * (item.発注数量 || 0);
    });
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 商品検索
  function searchProducts() {
    const category = container.querySelector('#category-select').value;
    const searchTerm = container.querySelector('#product-search').value.toLowerCase();

    let filteredProducts = allProducts;

    if (category) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === category);
    }

    if (searchTerm) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchTerm) ||
        (p.商品コード || '').toLowerCase().includes(searchTerm)
      );
    }

    renderProductList(filteredProducts);
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return false;
    }

    if (!deliveryDate) {
      alert('納期を指定してください');
      return false;
    }

    if (new Date(deliveryDate) <= new Date(orderDate)) {
      alert('納期は発注日より後の日付を指定してください');
      return false;
    }

    if (selectedProducts.length === 0) {
      alert('発注する商品を選択してください');
      return false;
    }

    // 発注数量のバリデーション
    for (let item of selectedProducts) {
      if (!item.発注数量 || item.発注数量 <= 0) {
        alert('発注数量は1以上で入力してください');
        return false;
      }
      if (isNaN(item.発注数量)) {
        alert('発注数量は数値で入力してください');
        return false;
      }
    }

    return true;
  }

  // 発注書作成
  async function createOrder() {
    if (!validateForm()) return;

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;
    const memo = container.querySelector('#order-memo').value;

    try {
      // 各商品の発注データを作成
      for (let item of selectedProducts) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.商品ID,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: item.発注数量,
          予測数量: demandPredictions.find(p => p.商品ID === item.商品ID)?.予測数量 || 0,
          発注単価: item.単価,
          発注金額: item.単価 * item.発注数量,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: item.仕入先ID || '',
          発注理由: memo,
          自動発注フラグ: false,
          作成者ID: 'current-user',
          更新者ID: 'current-user'
        };

        await window.aivicApi.save(10, orderData); // 発注データテーブル
      }

      alert('発注書が正常に作成されました');

      // フォームをリセット
      selectedProducts = [];
      renderSelectedProducts();
      container.querySelector('#order-memo').value = '';

      // 発注管理画面に遷移
      window.showScreen('scr-1778591852463');

    } catch (error) {
      alert('発注書の作成に失敗しました');
      console.error(error);
    }
  }

  // イベントリスナーの設定
  container.querySelector('#btn-search-product').addEventListener('click', searchProducts);

  container.querySelector('#btn-create-order').addEventListener('click', createOrder);

  container.querySelector('#btn-cancel').addEventListener('click', () => {
    window.showScreen('scr-1778591852463');
  });

  container.querySelector('#btn-calculate-total').addEventListener('click', () => {
    updateTotalAmount();
    alert(`発注総額: ${container.querySelector('#total-amount').textContent}`);
  });

  container.querySelector('#btn-stock-check').addEventListener('click', () => {
    container.querySelector('#stock-modal').classList.remove('hidden');
  });

  container.querySelector('#btn-history-check').addEventListener('click', () => {
    container.querySelector('#history-modal').classList.remove('hidden');
  });

  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#prediction-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-stock-modal').addEventListener('click', () => {
    container.querySelector('#stock-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-history-modal').addEventListener('click', () => {
    container.querySelector('#history-modal').classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    // 商品追加
    if (e.target.classList.contains('add-product-btn')) {
      const productId = e.target.dataset.productId;
      const product = allProducts.find(p => p.商品ID === productId);
      const quantityInput = e.target.closest('tr').querySelector('.quantity-input');
      const quantity = parseInt(quantityInput.value) || 0;

      if (quantity <= 0) {
        alert('発注数量は1以上で入力してください');
        return;
      }

      if (selectedProducts.find(p => p.商品ID === productId)) {
        alert('この商品は既に選択されています');
        return;
      }

      selectedProducts.push({
        ...product,
        発注数量: quantity
      });

      renderSelectedProducts();
    }

    // 商品削除
    if (e.target.classList.contains('remove-product-btn')) {
      const productId = e.target.dataset.productId;
      selectedProducts = selectedProducts.filter(p => p.商品ID !== productId);
      renderSelectedProducts();
    }

    // 予測根拠表示
    if (e.target.classList.contains('prediction-btn')) {
      const productId = e.target.dataset.productId;
      const prediction = demandPredictions.find(p => p.商品ID === productId);
      if (prediction) {
        container.querySelector('#prediction-accuracy').textContent = `${prediction.予測精度 || 85}%`;
      }
      container.querySelector('#prediction-modal').classList.remove('hidden');
    }
  });

  // 数量変更時の処理
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      if (e.target.classList.contains('selected-quantity')) {
        // 選択商品の数量変更
        const productId = e.target.dataset.productId;
        const quantity = parseInt(e.target.value) || 0;
        const product = selectedProducts.find(p => p.商品ID === productId);
        if (product) {
          product.発注数量 = quantity;
          updateTotalAmount();

          // 小計の更新
          const subtotalCell = e.target.closest('tr').querySelector('.subtotal');
          const subtotal = (product.単価 || 0) * quantity;
          subtotalCell.textContent = `¥${subtotal.toLocaleString()}`;
        }
      } else {
        // 商品一覧の数量変更
        updateSubtotals();
      }
    }
  });

  // 初期データの読み込み
  loadStores();
  loadProducts();
  loadDemandPredictions();
}
